package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lowercasing and removing spaces and
// punctuation), arranges it into an r x c rectangle with c = ceil(sqrt(n)),
// and returns the columns read left to right, separated by spaces. Columns
// shorter than r are padded with a trailing space.
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(toLower(r))
		}
	}
	n := b.Len()
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := int(math.Ceil(float64(n) / float64(c)))

	s := b.String()
	chunks := make([]string, c)
	for j := 0; j < c; j++ {
		var col strings.Builder
		for i := 0; i < r; i++ {
			if i*c+j < n {
				col.WriteByte(s[i*c+j])
			} else {
				col.WriteByte(' ')
			}
		}
		chunks[j] = col.String()
	}
	return strings.Join(chunks, " ")
}

func toLower(r rune) rune {
	if r >= 'A' && r <= 'Z' {
		return r + ('a' - 'A')
	}
	return r
}

